import React from "react";
import { useDispatch, useSelector } from "react-redux";
import { Link, useNavigate } from "react-router-dom";
import { logout } from "../Features/UserSlice";
import "../Styles/Header.css";

const Header = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();

  // Read user info and role from Redux
  const { user } = useSelector((state) => state.users);
  const role = user?.role; // role can be "student" or "company"

  // Logout and clear Redux state
  const handleLogout = () => {
    dispatch(logout()); // clear redux user data
    navigate("/login"); // redirect to login page
  };

  return (
    <header className="header">
      {/* App logo */}
      <div className="brand">
        <div className="logo-circle">UL</div>
        <div className="brand-text">
          <span className="brand-main">UTAS</span>
          <span className="brand-accent">Link</span>
        </div>
      </div>

      {/* Navigation links */}
      <nav className="nav-links">
        <Link to="/">Home</Link>

        {/* Links for Student */}
        {role === "student" && (
          <>
            <Link to="/findjob">Find Job</Link>
            <Link to="/myapplications">My Applications</Link>
            <Link to="/userprofile">Profile</Link>
            <button onClick={handleLogout} className="logout-btn">
              Logout
            </button>
          </>
        )}

        {/* Links for Company */}
        {role === "company" && (
          <>
            <Link to="/companyprofile">Company Profile</Link>
            <Link to="/postjob">Post Job</Link>
            <Link to="/companyjobs">My Jobs</Link>
            <Link to="/applicantsjob">Applicants</Link>
            <Link to="/chatpage">Chat</Link>
            <button onClick={handleLogout} className="logout-btn">
              Logout
            </button>
          </>
        )}

        {/* Links for not logged in users */}
        {!role && (
          <>
            <Link to="/login">Login</Link>
            <Link to="/user-register">Register</Link>
          </>
        )}
      </nav>
    </header>
  );
};

export default Header;
